<script setup lang="ts">
import {onMounted,watch} from 'vue';
import type {ApiClient} from '@kuaixie/sdk';
import {t,formatDate} from '@kuaixie/i18n';
import {usePaymentRefunds,paymentRefundStateKey,paymentRefundEventKey} from './usePaymentRefunds';
const props=defineProps<{client:ApiClient;admin?:boolean;refundId?:string}>();
const p=usePaymentRefunds(props.client,async(title,body)=>window.confirm(title+'\n'+body),!!props.admin);
watch(()=>props.refundId,id=>{if(id)void p.loadDetail(id)},{immediate:true});
onMounted(()=>{void p.loadList();void p.loadEligible()});
</script>
<template><section class="payment-refunds business-card"><h2>{{t('refund.title')}}</h2><p>{{t('refund.boundary')}}</p><p>{{t('refund.reserveNotice')}}</p><p>{{t('refund.onceNotice')}}</p><p v-if="p.error.value" role="alert">{{p.error.value}}</p><p v-if="p.notice.value" role="status">{{p.notice.value}}</p><p v-if="p.loading.value">{{t('account.loading')}}</p><button :disabled="p.busy.value||p.confirming.value||p.loading.value" @click="p.loadList();p.loadEligible()">{{t('refund.reload')}}</button>
<form v-if="!admin" @submit.prevent="p.apply()"><fieldset :disabled="p.locked.value"><legend>{{t('refund.apply')}}</legend><label>{{t('refund.payment')}}<select v-model="p.paymentId.value"><option value="">—</option><option v-for="row in p.eligible.value" :key="row.id" :value="row.id">{{row.merchantName}} · {{row.baseAmount}} CNY · {{row.id}}</option></select></label><p v-if="!p.eligible.value.length&&!p.loading.value">{{t('refund.noEligible')}}</p><p v-if="p.selected.value">{{t('refund.fullAmount')}}: {{p.selected.value.paymentAmount}} {{p.selected.value.paymentCurrency}}</p><label>{{t('refund.reason')}}<textarea v-model="p.reason.value" maxlength="200" required/></label><button>{{t('refund.apply')}}</button></fieldset><button v-if="p.pending.value" :disabled="p.busy.value||p.confirming.value" type="submit">{{t('refund.retryOriginal')}}</button></form>
<p v-if="p.pending.value">{{t('refund.pending')}}</p><p v-if="p.uncertain.value">{{t('refund.uncertainAction')}}</p><p v-if="!p.rows.value.length&&!p.loading.value">{{t('refund.empty')}}</p><article v-for="row in p.rows.value" :key="row.id"><button :disabled="p.locked.value||p.loading.value" @click="p.loadDetail(row.id)">{{row.paymentId}} · {{t(paymentRefundStateKey(row.status))}}</button><span>{{row.paymentAmount}} {{row.paymentCurrency}} · {{formatDate(row.createdAt)}}</span></article><button v-if="p.more.value" :disabled="p.loading.value" @click="p.loadList(true)">{{t('account.more')}}</button>
<section v-if="p.entry.value" class="refund-detail"><h3>{{t(paymentRefundStateKey(p.entry.value.status))}}</h3><dl><dt>{{t('refund.id')}}</dt><dd>{{p.entry.value.id}}</dd><dt>{{t('refund.payment')}}</dt><dd>{{p.entry.value.paymentId}}</dd><dt>{{t('refund.fullAmount')}}</dt><dd>{{p.entry.value.paymentAmount}} {{p.entry.value.paymentCurrency}}</dd><dt>{{t('refund.walletReserve')}}</dt><dd>{{p.entry.value.baseAmount}} {{p.entry.value.baseCurrency}}</dd><dt>{{t('refund.reason')}}</dt><dd>{{p.entry.value.reason}}</dd><dt>{{t('refund.reviewReason')}}</dt><dd>{{p.entry.value.reviewNote||'—'}}</dd><dt>{{t('refund.providerReference')}}</dt><dd>{{p.entry.value.providerRefundId||'—'}}</dd><dt>{{t('refund.updated')}}</dt><dd>{{formatDate(p.entry.value.updatedAt)}}</dd></dl><p v-if="p.entry.value.lastError">{{t('refund.providerIssue')}}</p><p v-if="p.entry.value.status==='succeeded'">{{t('refund.successRecorded')}}</p><button :disabled="p.busy.value||p.confirming.value||p.loading.value||!!p.pending.value" @click="p.loadDetail(p.entry.value.id)">{{t('refund.readCurrent')}}</button><button v-if="p.canRefresh.value" :disabled="p.busy.value" @click="p.refresh()">{{t('refund.queryProvider')}}</button><button v-if="p.canCancel.value" @click="p.cancel()">{{t('refund.cancel')}}</button><template v-if="admin&&p.entry.value.status==='requested'"><label>{{t('refund.reviewReason')}}<textarea v-model="p.reviewReason.value" maxlength="200" :disabled="p.locked.value"/></label><button :disabled="!p.canReview.value" @click="p.review(true)">{{t('refund.approve')}}</button><button :disabled="!p.canReview.value" @click="p.review(false)">{{t('refund.reject')}}</button></template><button v-if="admin&&p.entry.value.status==='approved'" :disabled="!p.canDispatch.value" @click="p.dispatch()">{{t('refund.dispatch')}}</button><h3>{{t('refund.timeline')}}</h3><p v-if="p.eventsLoading.value">{{t('account.loading')}}</p><article v-for="event in p.events.value" :key="event.id"><strong>{{t(paymentRefundEventKey(event.action))}}</strong><span>{{formatDate(event.createdAt)}}</span><p v-if="admin">{{event.detail}}</p></article><button v-if="p.moreEvents.value" :disabled="p.eventsLoading.value" @click="p.loadEvents(p.entry.value.id,true)">{{t('account.more')}}</button></section></section></template>
<style scoped>.payment-refunds{display:grid;gap:12px}.payment-refunds form,.payment-refunds fieldset{display:grid;gap:12px}.payment-refunds label{display:grid;gap:6px}.payment-refunds input,.payment-refunds select,.payment-refunds textarea{padding:10px;max-width:100%;box-sizing:border-box}.payment-refunds textarea{min-height:80px}.payment-refunds article{display:grid;gap:7px;padding:14px 0;border-bottom:1px solid #cbd5e1}.payment-refunds button{padding:10px;cursor:pointer}.payment-refunds dd{margin:5px 0 12px;overflow-wrap:anywhere}.payment-refunds [role=alert]{color:#b42318}</style>
